// Map Zulip emoji reaction → approval verb, and extract the action tuple
// from the machine-readable meta footer that approval-request embedded in the
// message content. The footer format (single line, inline code) is:
//   `lg-approval-meta task_id=<uuid> class=<A|B|C> server=<name> method=<name>`
// errand_runner._verify_approval_token requires the HMAC be signed over
// (task_id, action_class, server, method, nonce) where the first four match
// state.approval_request. If the meta footer is missing (older messages or a
// hand-edited Zulip post), we fall back to topic-based task_id extraction +
// placeholder tuple; errand-runner will reject the mismatch and the workflow
// stays paused, which is the fail-safe behavior.
const payload = $input.first().json.body || {};
const reactionRaw = (payload.data || '').toLowerCase();
const msg = payload.message || {};
const topic = msg.subject || payload.topic || '';
const content = msg.content || '';
const senderEmail = msg.sender_email || payload.actor || 'unknown';
let reaction = null;
if (reactionRaw.includes('thumbs_up') || reactionRaw.includes('+1') || reactionRaw.includes('check')) reaction = 'approve';
else if (reactionRaw.includes('thumbs_down') || reactionRaw.includes('-1') || reactionRaw.includes('x')) reaction = 'reject';
else if (reactionRaw.includes('pause') || reactionRaw.includes('clock') || reactionRaw.includes('hourglass')) reaction = 'defer';
if (!reaction) {
  return [{ json: { skip: true, reason: 'unrecognized reaction: ' + reactionRaw } }];
}
// Try the meta footer first — carries the canonical full task_id + action tuple.
const metaRe = /lg-approval-meta\s+task_id=([^\s`]+)\s+class=([^\s`]+)\s+server=([^\s`]+)\s+method=([^\s`]+)/;
const metaMatch = content.match(metaRe);
if (metaMatch) {
  const [, task_id, action_class, server, method] = metaMatch;
  return [{ json: { task_id, action_class, server, method, reaction, actor: senderEmail.split('@')[0] || 'rob' } }];
}
// Fallback: parse task_id from topic if approval-request didn't embed the footer.
const taskMatch = topic.match(/approval-([a-f0-9-]{8,})/i);
if (!taskMatch) {
  return [{ json: { skip: true, reason: 'no meta footer and topic does not match approval-<task_id>: ' + topic } }];
}
return [{ json: { task_id: taskMatch[1], action_class: 'C', server: 'unknown', method: 'unknown', reaction, actor: senderEmail.split('@')[0] || 'rob' } }];

// HMAC contract (matches errand_runner._verify_approval_token):
//   payload = task_id|action_class|server|method|nonce
//   token   = payload + ':' + hex(hmac-sha256(LANGGRAPH_APPROVAL_SIGNING_KEY, payload))
// The action tuple is now round-tripped from approval-request via the meta footer
// in the Zulip message content — see Parse Reaction. action_class/server/method
// on the input are the values approval-request originally sent. errand-runner
// verifies them against state.approval_request and rejects mismatches.
const crypto = require('crypto');
const signingKey = $env.LANGGRAPH_APPROVAL_SIGNING_KEY;
if (!signingKey) {
  throw new Error('LANGGRAPH_APPROVAL_SIGNING_KEY env var is not set on n8n; cannot mint tokens.');
}
const { task_id, action_class, server, method, reaction, actor } = $input.first().json;
const nonce = crypto.randomBytes(8).toString('hex');
const payload = [task_id, action_class, server, method, nonce].join('|');
const signature = crypto.createHmac('sha256', signingKey).update(payload).digest('hex');
const approval_token = payload + ':' + signature;
return [{ json: { task_id, reaction, actor, approval_token } }];
